def choose_profile(console: Console, current_profile: str) -> str:
    console.print("Choose a Gemma profile:")
    ordered_keys = ["gemma4-e2b", "gemma4-e4b", "gemma4-26b-laptop", "gemma4-26b-moe", "gemma4-31b"]
    for index, key in enumerate(ordered_keys, start=1):
        profile = GEMMA_PROFILES[key]
        hint = PROFILE_HINTS[key]
        marker = " default" if key == current_profile else ""
        short = profile.key.replace("gemma4-", "")
        console.print(f"  {index}. {short} [{hint}]{marker}")
    raw = input(f"Select profile [1-{len(ordered_keys)}] or press Enter for {current_profile}: ").strip()
    if not raw:
        return current_profile
    if raw.isdigit():
        idx = int(raw)
        if 1 <= idx <= len(ordered_keys):
            return ordered_keys[idx - 1]
    lowered = raw.lower()
    if lowered in ALIASES:
        return ALIASES[lowered]
    if lowered in GEMMA_PROFILES:
        return lowered
    console.print(f"Unknown choice '{raw}', using {current_profile}.")
    return current_profile

def choose_runtime_provider(console: Console, machine: MachineProfile, preset: PerformancePreset, current_provider: str) -> str:
    console.print("Choose a local runtime:")
    choices = [
        ("ollama", "easiest setup"),
        ("mlx-local", "best Apple Silicon path for MLX quantized Gemma"),
        ("llama_cpp", "best GGUF / tuned performance path"),
        ("huggingface-local", "advanced custom local checkpoints"),
    ]
    if machine.system != "darwin":
        choices = [item for item in choices if item[0] != "mlx-local"]
    default = preset.runtime_provider or current_provider
    for index, (key, label) in enumerate(choices, start=1):
        marker = " default" if key == default else ""
        console.print(f"  {index}. {key} [{label}]{marker}")
    raw = input(f"Select runtime [1-{len(choices)}] or press Enter for {default}: ").strip()
    if not raw:
        return default
    if raw.isdigit():
        idx = int(raw)
        if 1 <= idx <= len(choices):
            return choices[idx - 1][0]
    lowered = raw.lower()
    for key, _label in choices:
        if lowered == key:
            return key
    console.print(f"Unknown choice '{raw}', using {default}.")
    return default

def prompt_model_tag(console: Console, provider: str, current_model: str) -> str:
    hints = {
        "ollama": "example: gemma4:e4b",
        "mlx-local": "example: mlx-community/gemma-4-31b-it-4bit",
        "llama_cpp": "example: gemma4-27b-it-Q4_K_M.gguf",
        "huggingface-local": "example: google/gemma-4-27b-it-awq",
    }
    prompt = f"Optional model tag for {provider} [{hints.get(provider, 'leave empty for default')}]"
    raw = input(f"{prompt} or press Enter to keep {current_model or 'the profile default'}: ").strip()
    return raw or current_model

def _apply_model_routing(config: AppConfig, model_name: str) -> None:
    recommendation = recommend_for_model_tag(model_name)
    config.runtime.provider = recommendation.backend
    config.runtime.quant_preset = recommendation.quant_preset
    if recommendation.model_id_field == "mlx_model_id":
        config.runtime.mlx_model_id = model_name
        config.runtime.huggingface_model_id = ""
    elif recommendation.model_id_field == "huggingface_model_id":
        config.runtime.huggingface_model_id = model_name
        config.runtime.mlx_model_id = ""
    else:
        config.runtime.mlx_model_id = ""
        config.runtime.huggingface_model_id = ""

def run_runtime_wizard(
    console: Console,
    config: AppConfig,
    profile_name: str | None,
    model_name: str | None,
    benchmark: bool,
    assume_defaults: bool = False,
) -> tuple[str, str | None]:
    machine, preset = benchmark_report(config)
    if should_promote_legacy_default_to_laptop_26b(config, machine):
        apply_preset(config, preset, model=model_name or config.runtime.model)
    if benchmark:
        apply_preset(config, preset, model=model_name or config.runtime.model)
        console.print(f"Detected machine tier: {machine.tier}")
        console.print(f"Recommended mode: {preset.mode}")
        if preset.profile == "gemma4-26b-laptop":
            console.print("26B laptop mode: automatic Apple Silicon runtime selection enabled.")
        for note in preset.notes:
            console.print(f"- {note}")
    if assume_defaults:
        provider = preset.runtime_provider or config.runtime.provider
        config.runtime.provider = provider
        selected_profile = profile_name or config.runtime.profile or preset.profile
        chosen_model = model_name or config.runtime.model
        if chosen_model:
            _apply_model_routing(config, chosen_model)
        else:
            config.runtime.provider = provider
        return selected_profile, chosen_model or None
    provider = choose_runtime_provider(console, machine, preset, config.runtime.provider)

def __init__(self) -> None:
    self.dir = ensure_home_dirs() / "snapshots"
    self.dir.mkdir(exist_ok=True)

def load(self, snapshot_id: str) -> GhostSnapshot | None:
    """Load a snapshot by ID."""
    path = self.dir / f"{snapshot_id}.json"
    if not path.is_file():
        # Try prefix match
        matches = list(self.dir.glob(f"{snapshot_id}*.json"))
        if len(matches) == 1:
            path = matches[0]
        else:
            return None
    try:
        data = json.loads(path.read_text())
        return GhostSnapshot(
            id=data["id"],
            session_id=data["session_id"],
            repo_root=data["repo_root"],
            created_at=data["created_at"],
            reason=data["reason"],
            messages=data["messages"],
            pinned_files=data.get("pinned_files", []),
            file_snapshots=data.get("file_snapshots", {}),
            model=data.get("model", ""),
            label=data.get("label", ""),
        )
    except Exception:
        return None

def cleanup(self, max_age_days: int = 30) -> int:
    """Delete snapshots older than max_age_days."""
    cutoff = time.time() - (max_age_days * 86400)
    deleted = 0
    for path in self.dir.glob("*.json"):
        try:
            data = json.loads(path.read_text())
            if data.get("created_at", 0) < cutoff:
                path.unlink()
                deleted += 1
        except Exception:
            continue
    return deleted

def restore_snapshot(snapshot: GhostSnapshot) -> dict:
    """Restore file system state from a snapshot.

    Returns dict of files restored.
    """
    restored = {}
    root = Path(snapshot.repo_root)
    for rel_path, content in snapshot.file_snapshots.items():
        full = root / rel_path
        try:
            full.parent.mkdir(parents=True, exist_ok=True)
            full.write_text(content)
            restored[rel_path] = "restored"
        except Exception as e:
            restored[rel_path] = f"error: {e}"
    return restored

def _load_hooks(self) -> HookConfig:
    """Load hooks from project .gem/hooks.toml, then global ~/.gem/hooks.toml."""
    config = HookConfig()

    # Global hooks (lower priority)
    global_path = Path.home() / ".gem" / "hooks.toml"
    if global_path.is_file():
        self._merge_hooks(config, global_path)

    # Project hooks (higher priority — overrides global)
    project_path = Path(self.repo_root) / ".gem" / "hooks.toml"
    if project_path.is_file():
        self._merge_hooks(config, project_path)

    return config

@staticmethod

def _merge_hooks(config: HookConfig, path: Path) -> None:
    """Merge hooks from a TOML file into the config."""
    try:
        data = tomllib.loads(path.read_text())
        hooks = data.get("hooks", {})
        for key in ("session_start", "user_prompt_submit", "pre_tool_use", "post_tool_use"):
            val = hooks.get(key, "")
            if val:
                setattr(config, key, val)
    except Exception:
        pass

# ── Hook execution ──────────────────────────────────────────────

def on_session_start(self) -> HookResult:
    """Run session_start hook."""
    if not self.config.session_start:
        return HookResult()
    return self._run(self.config.session_start, {})

def on_user_prompt_submit(self, prompt: str) -> HookResult:
    """Run user_prompt_submit hook. Non-zero exit = block the prompt."""
    if not self.config.user_prompt_submit:
        return HookResult()
    return self._run(self.config.user_prompt_submit, {"PROMPT": prompt})

def on_pre_tool_use(self, tool_name: str, tool_args: dict) -> HookResult:
    """Run pre_tool_use hook. Non-zero exit = block the tool call."""
    if not self.config.pre_tool_use:
        return HookResult()
    import json
    return self._run(self.config.pre_tool_use, {
        "TOOL_NAME": tool_name,
        "TOOL_ARGS": json.dumps(tool_args, default=str)[:500],
    })

def on_post_tool_use(self, tool_name: str, tool_args: dict,
                     result: str, error: bool = False) -> HookResult:
    """Run post_tool_use hook (informational, can't block)."""
    if not self.config.post_tool_use:
        return HookResult()
    import json
    return self._run(self.config.post_tool_use, {
        "TOOL_NAME": tool_name,
        "TOOL_ARGS": json.dumps(tool_args, default=str)[:500],
        "TOOL_RESULT": result[:500],
        "TOOL_ERROR": "1" if error else "0",
    })

def _run(self, command: str, extra_env: dict[str, str]) -> HookResult:
    """Execute a hook command."""
    env = {**self._base_env, **extra_env}
    try:
        proc = subprocess.run(
            command,
            shell=True,
            capture_output=True,
            text=True,
            timeout=10,
            cwd=self.repo_root,
            env=env,
        )
        return HookResult(
            ran=True,
            blocked=(proc.returncode != 0),
            output=proc.stdout.strip()[:500],
            error=proc.stderr.strip()[:500],
            exit_code=proc.returncode,
        )
    except subprocess.TimeoutExpired:
        return HookResult(ran=True, blocked=False, error="hook timed out (10s)")
    except Exception as exc:
        return HookResult(ran=True, blocked=False, error=str(exc)[:200])

@property

def preview_and_apply(self, action: EditAction) -> EditResult:
    """Show diff, get approval, apply if approved."""
    full_path = self.root / action.file_path

    if action.edit_type == "create":
        return self._handle_create(action, full_path)
    elif action.edit_type == "full_write":
        return self._handle_full_write(action, full_path)
    elif action.edit_type == "search_replace":
        return self._handle_search_replace(action, full_path)
    else:
        return EditResult(action.file_path, False, f"unknown edit type: {action.edit_type}")

# ── Batch edit ──────────────────────────────────────────────────

def format_diff_colored(self, diff_lines: list[str],
                        max_lines: int | None = None) -> str:
    """Format diff with ANSI colors."""
    if max_lines is None:
        max_lines = self.max_diff_lines

    lines = []
    shown = 0
    total = len(diff_lines)

    for line in diff_lines:
        if shown >= max_lines:
            remaining = total - shown
            lines.append(f"{DIM}  ... +{remaining} more lines{RESET}")
            break

        if line.startswith("+++") or line.startswith("---"):
            lines.append(f"  {BOLD}{line}{RESET}")
        elif line.startswith("@@"):
            lines.append(f"  {CYAN}{line}{RESET}")
        elif line.startswith("+"):
            lines.append(f"  {GREEN}{line}{RESET}")
        elif line.startswith("-"):
            lines.append(f"  {RED}{line}{RESET}")
        else:
            lines.append(f"  {DIM}{line}{RESET}")
        shown += 1

    return "\n".join(lines)

def _handle_create(self, action: EditAction, full_path: Path) -> EditResult:
    """Handle creating a new file."""
    content = action.full_content
    lines = content.splitlines()
    line_count = len(lines)

    # Show preview
    sys.stdout.write(f"\n{BOLD}  Create new file: {action.file_path}{RESET}\n")
    preview_lines = min(20, line_count)
    for i, line in enumerate(lines[:preview_lines], 1):
        sys.stdout.write(f"  {GREEN}+{i:4d} │ {line}{RESET}\n")
    if line_count > preview_lines:
        sys.stdout.write(f"  {DIM}  ... +{line_count - preview_lines} more lines{RESET}\n")
    sys.stdout.write(f"\n  {DIM}{line_count} lines total{RESET}\n\n")
    sys.stdout.flush()

    # Get approval
    if self.auto_approve:
        decision = "y"
    else:
        decision = self._ask_approval()

    if decision in ("n", "reject"):
        return EditResult(action.file_path, False, "rejected")
    if decision == "a":
        self._snapshot(action.file_path)
        full_path.parent.mkdir(parents=True, exist_ok=True)
        full_path.write_text(content)
        return EditResult(action.file_path, True, "apply_all",
                          lines_added=line_count, lines_removed=0)

def _handle_full_write(self, action: EditAction, full_path: Path) -> EditResult:
    """Handle overwriting an existing file."""
    if not full_path.is_file():
        # File doesn't exist — treat as create
        action.edit_type = "create"
        return self._handle_create(action, full_path)

    old_content = full_path.read_text(errors="replace")
    new_content = action.full_content

    if old_content == new_content:
        return EditResult(action.file_path, False, "no changes")

    # Generate and show diff
    diff = self.generate_diff(old_content, new_content, action.file_path)
    added, removed = self.diff_stats(diff)

    sys.stdout.write(f"\n{BOLD}  Overwrite: {action.file_path}{RESET}\n")
    sys.stdout.write(self.format_diff_colored(diff) + "\n")
    sys.stdout.write(f"\n  {DIM}-{removed} +{added} lines{RESET}\n\n")
    sys.stdout.flush()

    # Get approval
    if self.auto_approve:
        decision = "y"
    else:
        decision = self._ask_approval()

    if decision in ("n", "reject"):
        return EditResult(action.file_path, False, "rejected")

def _handle_search_replace(self, action: EditAction, full_path: Path) -> EditResult:
    """Handle a search/replace edit."""
    if not full_path.is_file():
        return EditResult(action.file_path, False, f"file not found: {action.file_path}")

    content = full_path.read_text(errors="replace")

    # Validate search string exists
    count = content.count(action.old_string)
    if count == 0:
        return EditResult(action.file_path, False,
                          "error: search string not found in file")
    if count > 1:
        return EditResult(action.file_path, False,
                          f"error: search string matches {count} locations (ambiguous)")

    # Generate diff
    new_content = content.replace(action.old_string, action.new_string, 1)
    diff = self.generate_diff(content, new_content, action.file_path)
    added, removed = self.diff_stats(diff)

