        return GEMMA_PROFILES[ALIASES[name]]
    for profile in GEMMA_PROFILES.values():
        if profile.default_model in name or name in profile.default_model:
            return profile
    if "31b" in name:
        return GEMMA_PROFILES["gemma4-31b"]
    if "26b-laptop" in name:
        return GEMMA_PROFILES["gemma4-26b-laptop"]
    if "26b" in name:
        return GEMMA_PROFILES["gemma4-26b-moe"]
    return None

def resolve_profile(profile_name: str | None, explicit_model: str | None) -> ModelProfile:
    normalized = (profile_name or "gemma4-e4b").strip().lower()
    if normalized in ALIASES:
        return GEMMA_PROFILES[ALIASES[normalized]]
    if normalized in GEMMA_PROFILES:
        return GEMMA_PROFILES[normalized]
    inferred = infer_profile_from_model(explicit_model or "")
    return inferred or GEMMA_PROFILES["gemma4-e4b"]

def get_runtime_model(profile: ModelProfile, explicit_model: str | None) -> str:
    if explicit_model and explicit_model.strip():
        return explicit_model.strip()
    return profile.default_model

class ApprovalItem:
    label: str
    detail: str

def __init__(self, console: Console, prompt: PromptSession) -> None:
    self.console = console
    self.prompt = prompt

def review(self, title: str, items: list[ApprovalItem], allow_repo_option: bool = False, allow_session_option: bool = True) -> str:
    table = Table("action", "details")
    for item in items:
        table.add_row(item.label, item.detail[:300])
    self.console.print(Panel.fit(table, title=title))
    suffix = "[a]ll once/[n]o/[v]iew"
    if allow_session_option:
        suffix += "/[s]ession-allow"
    if allow_repo_option:
        suffix += "/[r]epo-allow"
    while True:
        raw = self.prompt.prompt(f"Approve {title}? {suffix} ").strip().lower()
        if raw in {"", "a", "all"}:
            return "allow"
        if raw in {"n", "no"}:
            return "deny"
        if raw in {"v", "view"}:
            self.console.print(Panel("\n\n".join(f"{item.label}\n{item.detail}" for item in items), title=f"{title} details"))
            continue
        if allow_session_option and raw in {"s", "session-allow"}:
            return "session-allow"
        if allow_repo_option and raw in {"r", "repo-allow"}:
            return "repo-allow"

def skill_dirs(repo_root: Path) -> list[Path]:
    return [
        ensure_home_dirs() / "skills",
        repo_root / ".gem" / "skills",
    ]

def list_skills(repo_root: Path) -> list[str]:
    names: set[str] = set()
    for directory in skill_dirs(repo_root):
        if not directory.exists():
            continue
        for path in directory.glob("*.md"):
            names.add(path.stem)
    return sorted(names)

def load_skill(repo_root: Path, name: str) -> str | None:
    for directory in skill_dirs(repo_root):
        path = directory / f"{name}.md"
        if path.exists():
            return path.read_text(errors="replace")
    return None

def resolve_referenced_skills(repo_root: Path, text: str) -> list[tuple[str, str]]:
    resolved: list[tuple[str, str]] = []
    seen: set[str] = set()
    for name in SKILL_PATTERN.findall(text):
        if name in seen:
            continue
        content = load_skill(repo_root, name)
        if content:
            resolved.append((name, content))
            seen.add(name)
    return resolved


