def collect_typeahead(self) -> None:
    """Non-blocking: collect keystrokes into queue while model works.

    Called by indicator thread. Sets raw mode once, reads all available
    chars, then restores. The indicator thread redraws the input field
    showing the buffer text.
    """
    buf = getattr(self, '_typeahead_buf', [])
    fd = sys.stdin.fileno()
    try:
        if not select.select([sys.stdin], [], [], 0)[0]:
            return  # nothing to read
        old = termios.tcgetattr(fd)
        try:
            tty.setcbreak(fd)  # cbreak: chars available immediately, no echo
            while select.select([sys.stdin], [], [], 0)[0]:
                ch = os.read(fd, 1).decode("utf-8", errors="replace")
                if ch in ("\r", "\n"):
                    text = "".join(buf).strip()
                    if text:
                        with self._lock:
                            self._queue.append(text)
                        self._save_history(text)
                    buf.clear()
                elif ch == "\x7f" or ch == "\x08":
                    if buf:
                        buf.pop()
                elif ch == "\x03":
                    buf.clear()
                elif ch == "\x15":  # Ctrl+U

def get_typeahead_text(self) -> str:
    """Return current typeahead buffer text (for display in indicator)."""
    buf = getattr(self, '_typeahead_buf', [])
    return "".join(buf)

def _save_history(self, text: str) -> None:
    if text and (not self._history or self._history[-1] != text):
        self._history.append(text)
        if self._history_file:
            try:
                with open(self._history_file, "a") as f:
                    f.write(f"+{text}\n")
            except Exception:
                pass

def _build_user_message(
    text: str,
    images: list[str] | None,
    profile: ModelProfile,
    provider: str,
) -> dict:
    """Build a user message, handling images per provider format."""
    if not images or not profile.supports_vision:
        return {"role": "user", "content": text}

    if provider in ("huggingface-local", "mlx-local"):
        # HF/MLX: multipart content array
        # Format: [{"type": "image", "image": base64}, {"type": "text", "text": "..."}]
        content_parts: list[dict] = []
        for img_b64 in images:
            content_parts.append({"type": "image", "image": f"data:image/png;base64,{img_b64}"})
        content_parts.append({"type": "text", "text": text})
        return {"role": "user", "content": content_parts}

    if provider == "llama_cpp":
        # llama-server: OpenAI-compatible multipart content
        content_parts: list[dict] = []
        for img_b64 in images:
            content_parts.append({
                "type": "image_url",
                "image_url": {"url": f"data:image/png;base64,{img_b64}"},
            })
        content_parts.append({"type": "text", "text": text})
        return {"role": "user", "content": content_parts}

