def _capture_stdout(self) -> None:
    if self.proc.stdout is None:
        return
    for line in self.proc.stdout:
        line = line.strip()
        if not line:
            continue
        try:
            self._stdout_queue.put(json.loads(line))
        except Exception:
            continue

def _capture_stderr(self) -> None:
    if self.proc.stderr is None:
        return
    for line in self.proc.stderr:
        self._stderr_queue.put(line.rstrip("\n"))

def _request(self, method: str, params: dict[str, Any] | None = None) -> Any:
    with self._lock:
        self._request_id += 1
        req_id = self._request_id
        payload = {"jsonrpc": "2.0", "id": req_id, "method": method}
        if params is not None:
            payload["params"] = params
        assert self.proc.stdin is not None
        self.proc.stdin.write(json.dumps(payload) + "\n")
        self.proc.stdin.flush()
        deadline = time.time() + self.timeout_seconds
        while True:
            remaining = deadline - time.time()
            if remaining <= 0:
                raise RuntimeError(
                    f"MCP server {self.config.name} timed out during {method}; stderr={self.recent_stderr() or 'none'}"
                )
            try:
                data = self._stdout_queue.get(timeout=remaining)
            except Empty as exc:
                raise RuntimeError(
                    f"MCP server {self.config.name} timed out during {method}; stderr={self.recent_stderr() or 'none'}"
                ) from exc
            if data.get("id") == req_id:
                if "error" in data:
                    raise RuntimeError(str(data["error"]))
                return data.get("result")

def initialize(self) -> None:
    self._request(
        "initialize",
        {
            "protocolVersion": "2025-03-26",
            "capabilities": {},
            "clientInfo": {"name": "gem", "version": "0.1.0"},
        },
    )
    assert self.proc.stdin is not None
    self.proc.stdin.write(json.dumps({"jsonrpc": "2.0", "method": "notifications/initialized"}) + "\n")
    self.proc.stdin.flush()

def list_tools(self) -> list[dict[str, Any]]:
    result = self._request("tools/list", {})
    return list(result.get("tools", []))

def call_tool(self, name: str, arguments: dict[str, Any]) -> str:
    result = self._request("tools/call", {"name": name, "arguments": arguments})
    content = result.get("content", [])
    return "\n".join(item.get("text", "") for item in content if item.get("type") == "text") or json.dumps(result)

def close(self) -> None:
    if self.proc.poll() is None:
        self.proc.terminate()

def health(self) -> tuple[bool, str]:
    if self.proc.poll() is not None:
        return False, f"process exited with {self.proc.returncode}; stderr={self.recent_stderr() or 'none'}"
    return True, "running"

def recent_stderr(self, limit: int = 8) -> str:
    items: list[str] = []
    try:
        while True:
            items.append(self._stderr_queue.get_nowait())
    except Empty:
        pass
    return " | ".join(items[-limit:])

def load_project_context(repo_root: Path) -> str:
    """Load per-project context from GEM.md or .gem/context.md.

    Returns the combined content of all found context files,
    or empty string if none exist.
    """
    sections: list[str] = []
    for filename in CONTEXT_FILES:
        path = repo_root / filename
        if path.is_file():
            try:
                content = path.read_text(errors="replace").strip()
                if content:
                    sections.append(f"# Project instructions ({filename})\n{content}")
            except Exception:
                continue
    return "\n\n".join(sections)

def load_ignore_patterns(repo_root: Path) -> list[str]:
    """Load .gem/ignore patterns (one glob per line, like .gitignore)."""
    path = repo_root / IGNORE_FILE
    if not path.is_file():
        return []
    try:
        lines = path.read_text(errors="replace").splitlines()
        return [
            line.strip()
            for line in lines
            if line.strip() and not line.strip().startswith("#")
        ]
    except Exception:
        return []

def has_project_context(repo_root: Path) -> bool:
